def assemble_training_pipeline(values: ApplicationValues, environment: MutableMapping[str, str], ports: TrainingPipelineWiringInputs) -> TrainingPipelineAssembly:
    def runtime_postgres_repository_or_none() -> Any | None:
        """Return the explicit PostgreSQL repository, or None for JSON runtime."""
        return ports._runtime_repository_access().runtime_postgres_repository_or_none()

    def resource_owner_id_for_new_record(user: dict[str, Any]) -> str:
        return ports._resource_names().resource_owner_id_for_new_record(user)

    def task_record_name(record: dict[str, Any]) -> str:
        return ports._resource_names().task_record_name(record)

    def assert_unique_task_name(name: Any, owner_user_id: str, *, exclude_pipeline_task_id: str='', exclude_ai_task_id: str='') -> None:
        return ports._resource_names().assert_unique_task_name(name, owner_user_id, exclude_pipeline_task_id=exclude_pipeline_task_id, exclude_ai_task_id=exclude_ai_task_id)

    def assert_unique_dataset_name(name: Any, owner_user_id: str, user: dict[str, Any], *, exclude_dataset_id: str='') -> None:
        return ports._resource_names().assert_unique_dataset_name(name, owner_user_id, user, exclude_dataset_id=exclude_dataset_id)

    def assert_unique_model_name(name: Any, owner_user_id: str, *, exclude_run_id: str='') -> None:
        return ports._resource_names().assert_unique_model_name(name, owner_user_id, exclude_run_id=exclude_run_id)

    def set_training_state_for_user(config: dict[str, Any], user: dict[str, Any], training_state: dict[str, Any]) -> None:
        return _training_account_state.set_training_state_for_user(config, user, training_state)

    def sync_training_state_from_task(job_id: str) -> None:
        return _training_account_state.sync_training_state_from_task(job_id)

